#include <stdio.h>

typedef enum { INFO, WARN, ERROR } LogLevel;
const char* level_names[] = {"INFO", "WARN", "ERROR"};

void log_msg(int level, char *msg) {
    printf("[%s]: %s\n", level_names[level], msg);
}

#define LOG_INFO(msg) log_msg(INFO, msg)
#define LOG_WARN(msg) log_msg(WARN, msg)
#define LOG_ERROR(msg) log_msg(ERROR, msg)

int main() {
    LOG_INFO("Application started");
    LOG_WARN("Low memory");
    LOG_ERROR("File not found");
    return 0;
}
